// 组装 DeepSeek 感知请求体；signal 来自 webhook 输入
const signal = $json.body?.signal || $json.signal || JSON.stringify($json);
const model = (typeof $env !== 'undefined' && $env.DEEPSEEK_MODEL) || 'deepseek-v4-flash';
const payload = {
  model,
  messages: [
    { role: 'system', content: '你是通用 UC 的感知节点。从用户信号中抽取结构化事实，只输出 JSON 对象。格式：{"fields":{"summary":"一句话概括","entities":[],"facts":{}}}' },
    { role: 'user', content: signal },
  ],
  temperature: 0,
  max_tokens: 1200,
  response_format: { type: 'json_object' },
};
return { ...$json, payload };

// 从 DeepSeek 响应中抽取结构化事实；模型失败 = fail-closed
const content = $json?.choices?.[0]?.message?.content;
if (!content) throw new Error('PERCEIVE_FAIL: 感知模型返回空 content');
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('PERCEIVE_FAIL: 感知模型输出非法 JSON'); }
const fields = parsed?.fields && typeof parsed.fields === 'object' && !Array.isArray(parsed.fields) ? parsed.fields : { raw: parsed };
return { passed: true, fields, evidence: ['模型已抽取结构化事实'] };

// 组装 DeepSeek 决策请求体；fields 来自感知节点
const fields = $json.fields || $json;
const model = (typeof $env !== 'undefined' && $env.DEEPSEEK_MODEL) || 'deepseek-v4-flash';
const payload = {
  model,
  messages: [
    { role: 'system', content: '你是通用 UC 的决策节点。基于结构化事实给出行动建议与理由，只输出 JSON 对象。格式：{"recommendation":{"action":"建议动作","reason":"理由","risk":"风险"}}' },
    { role: 'user', content: JSON.stringify(fields) },
  ],
  temperature: 0,
  max_tokens: 1200,
  response_format: { type: 'json_object' },
};
return { ...$json, payload };

// 决策建议非空，否则 fail-closed
const content = $json?.choices?.[0]?.message?.content;
if (!content) throw new Error('DECIDE_FAIL: 决策模型返回空 content');
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('DECIDE_FAIL: 决策模型输出非法 JSON'); }
const recommendation = parsed?.recommendation ?? parsed;
if (!recommendation || typeof recommendation !== 'object') throw new Error('DECIDE_FAIL: 决策建议为空');
return { passed: true, recommendation };

// 验收 Gate（fail-closed）：人审决策必须合法，否则抛错让执行失败
const d = $json?.body || $json || {};
const okStatus = ['approved', 'deferred', 'rejected'].includes(d.status);
const passed = okStatus && !!d.actor_role && !!d.rationale;
const gate = { rule_id: 'T-A1', title: '人审决策合法', constraint: 'status 必须在 approved/deferred/rejected 内，且角色与理由非空', pass: passed, signal: passed ? null : (okStatus ? 'actor_role/rationale 缺失' : 'decision.status 非法') };
if (!passed) throw new Error('GATE_FAIL:' + JSON.stringify(gate));
return { decision: { actor_role: d.actor_role, status: d.status, rationale: d.rationale }, recommendation: $('ParseDecide').first().json.recommendation, gate };

// 学习复盘沉淀（骨架版，业务字段由实例替换）
const d = $json.decision;
const gate = $('AcceptGate').first().json.gate;
return { learning: { outcome: d.status, accepted: gate.pass, rules_applied: ['T-A1'], next_action: d.status === 'approved' ? '继续执行' : d.status === 'deferred' ? '责任人复核' : '按驳回重新评估' } };
